if (!root) {
    root = new TreeNode<int>(item);
    return;
}

if (item < root->data) {
    avlInsert(root->left, item);
} else if (item > root->data) {
    avlInsert(root->right, item);
} else {
    return;
}

int leftHeight = root->left ? root->left->height : 0;
int rightHeight = root->right ? root->right->height : 0;
root->height = 1 + std::max(leftHeight, rightHeight);

int balance = leftHeight - rightHeight;

if (balance > 1 && item < root->left->data) {
    avlRotateRight(root);
} else if (balance < -1 && item > root->right->data) {
    avlRotateLeft(root);
} else if (balance > 1 && item > root->left->data) {
    avlRotateLeft(root->left);
    avlRotateRight(root);
} else if (balance < -1 && item < root->right->data) {
    avlRotateRight(root->right);
    avlRotateLeft(root);
}

